changeSet.sql:
ALTER TABLE document.payment_requests RENAME COLUMN document_id TO contract_id;
ALTER TABLE document.payment_requests RENAME COLUMN payment_schedule_id TO payment_id;
ALTER TABLE document.payment_requests ADD COLUMN IF NOT EXISTS buyer_in TEXT;
ALTER TABLE document.payment_requests ADD COLUMN IF NOT EXISTS seller_in TEXT;
UPDATE document.payment_requests r
   SET buyer_in = c.buyer_in, seller_in = c.seller_in
  FROM document.contracts c WHERE c.id = r.contract_id;
ALTER TABLE document.payment_requests DROP COLUMN IF EXISTS user_id;
ALTER TABLE document.payment_requests DROP COLUMN IF EXISTS type;

ALTER TABLE document.delay_requests RENAME COLUMN document_id TO contract_id;
ALTER TABLE document.delay_requests RENAME COLUMN payment_schedule_id TO payment_id;
ALTER TABLE document.delay_requests ADD COLUMN IF NOT EXISTS buyer_in TEXT;
ALTER TABLE document.delay_requests ADD COLUMN IF NOT EXISTS seller_in TEXT;
UPDATE document.delay_requests r
   SET buyer_in = c.buyer_in, seller_in = c.seller_in
  FROM document.contracts c WHERE c.id = r.contract_id;
ALTER TABLE document.delay_requests DROP COLUMN IF EXISTS user_id;
ALTER TABLE document.delay_requests DROP COLUMN IF EXISTS type;
